It looks odd that we'd have to explicitly disable the auth check for every leaf command. I realize that annotations aren't inherited, but we could still collect all annotations by traversing any command upwards:

```go
func isAuthCheckEnabled(cmd *cobra.Command) bool {
  if !c.Runnable() {
    return false
  }
  for c := cmd; c.Parent() != nil; c = c.Parent() {
    if c.Annotations != nil && c.Annotations["skipAuthCheck"] == "true" {
      return false
    }
  }
  return true
}
```

Then we could just annotate commands immediately under root
